<?php
namespace Tests\Feature;use App\Models\Company;use App\Models\Job;use App\Models\JobApplication;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class AssessmentTest extends TestCase{use RefreshDatabase;public function test_company_creates_assigns_and_candidate_completes_test():void{$owner=User::factory()->create(['account_type'=>'company']);$company=Company::create(['name'=>'Acme','slug'=>'acme','status'=>'active']);$company->members()->attach($owner->id,['role'=>'owner','status'=>'active']);$job=Job::create(['company_id'=>$company->id,'slug'=>'job','title'=>'Developer','summary'=>'Job','location'=>'Santiago','modality'=>'Remoto','contract_type'=>'Tiempo completo','status'=>'active']);$candidate=User::factory()->create(['account_type'=>'candidate']);$application=JobApplication::create(['job_id'=>$job->id,'user_id'=>$candidate->id,'status'=>'evaluating','profile_snapshot'=>[],'applied_at'=>now()]);$assessment=$this->actingAs($owner,'sanctum')->postJson('/api/v1/company/assessments',['job_id'=>$job->id,'title'=>'PHP básico','duration_minutes'=>30,'questions'=>[['prompt'=>'¿Resultado de 2+2?','type'=>'single_choice','options'=>['3','4'],'correct_answer'=>'4']]])->assertCreated()->json('data.id');$assignment=$this->actingAs($owner,'sanctum')->postJson("/api/v1/company/assessments/{$assessment}/assign",['application_id'=>$application->id])->assertCreated()->json('data.id');$this->actingAs($candidate,'sanctum')->getJson('/api/v1/candidate/assessments')->assertOk()->assertJsonCount(1,'data');$this->actingAs($candidate,'sanctum')->postJson("/api/v1/candidate/assessments/{$assignment}/submit",['answers'=>['4']])->assertOk()->assertJsonPath('data.score','100.00');$this->actingAs($owner,'sanctum')->putJson("/api/v1/company/applications/{$application->id}/evaluation",['ratings'=>['communication'=>5,'technical'=>4],'recommendation'=>'Avanzar'])->assertOk();}}
